import{_ as e,o as a,c as o,a4 as s}from"./chunks/framework.BabNWGMA.js";const u=JSON.parse('{"title":"🎲 概率论 知识点笔记","description":"","frontmatter":{},"headers":[],"relativePath":"subjects/概率论.md","filePath":"subjects/概率论.md","lastUpdated":1789102210000}'),r={name:"subjects/概率论.md"};function n(l,t,c,p,_,d){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="🎲-概率论-知识点笔记" tabindex="-1">🎲 概率论 知识点笔记 <a class="header-anchor" href="#🎲-概率论-知识点笔记" aria-label="Permalink to &quot;🎲 概率论 知识点笔记&quot;">​</a></h1><blockquote><p>共 <strong>1</strong> 个知识点 · 隔天自动更新</p></blockquote><h2 id="随机事件与样本空间-古典概型" tabindex="-1">随机事件与样本空间(古典概型) <a class="header-anchor" href="#随机事件与样本空间-古典概型" aria-label="Permalink to &quot;随机事件与样本空间(古典概型)&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-09-24 | <strong>最近复习:</strong> 2026-09-24</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>随机试验 E 的三个特征:①在相同条件下可重复进行 ②所有可能结果事先已知且不止一个 ③每次试验前不知哪个结果出现。样本空间 Ω = 全部可能结果的集合;样本点 ω 是 Ω 的元素;随机事件 = Ω 的子集,事件发生 &lt;=&gt; 试验结果落在该子集内。必然事件 = Ω,不可能事件 = 空集。事件关系:包含 A⊂B;和(并) A∪B 表示「A、B 至少一个发生」;积(交) A∩B 表示「同时发生」;差 A-B;对立(逆) 事件 Ā = Ω-A,满足 A∪Ā=Ω 且 A∩Ā=空集。互斥(AB=空集)不一定对立,对立一定互斥。古典概型两个条件:①样本点个数有限 ②每个样本点等可能 =&gt; P(A) = A 所含样本点数 / Ω 中样本点总数。考察方式:先判断是否满足「有限+等可能」,再用组合计数,注意区分「有放回/无放回」「有序/无序」。</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>例:掷一枚均匀骰子,Ω={1,2,3,4,5,6};事件 A=「点数大于 4」={5,6},P(A)=2/6=1/3。再如掷两次骰子,两数之和为 2 只有 (1,1) 一种结果,样本点总数 36,故 P=1/36。</p></details><hr>',9)])])}const m=e(r,[["render",n]]);export{u as __pageData,m as default};
